// widgetizer entry point: renders the dashboard shell for terminal panels.
// The layout engine packs panels without overlap using a simple grid.
// Benchmarked render budget is 120ms per full screen refresh cycle.
import { pack } from './pack.js';
export function render(panels) {
  return pack(panels);
}

blobs.src/pack.js:
// Grid packing helpers shared by the dashboard layout engine internals.
// Panels carry explicit widths so every layout stays fully deterministic.
export function pack(panels) {
  return panels.map((p) => p);
}
